import { mergeSettings, type Settings } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, received ${String(actual)}`);
  }
}

function expectTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error: unknown) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: expected TypeError`);
  }
  throw new Error(`${message}: expected an exception`);
}

const emptyA = mergeSettings([]);
const emptyB = mergeSettings([]);
assert(Object.keys(emptyA).length === 0, 'empty input produces empty settings');
assert(emptyA !== emptyB, 'empty calls produce fresh objects');

const shared = { flag: true };
const arrayValue = [1, { deep: 'original' }, null] as const;
const first: Settings = {
  name: 'first',
  nested: { left: 1, replace: 'old' },
  atomic: [1, 2],
  explicit: 'present',
  onlyFirst: shared,
};
const second: Settings = {
  name: 'second',
  nested: { right: 2, replace: 'new' },
  atomic: arrayValue,
  explicit: undefined,
  onlySecond: shared,
};
const merged = mergeSettings([first, second]);

equal(merged.name, 'second', 'later scalar overrides earlier scalar');
const nested = merged.nested as Settings;
equal(nested.left, 1, 'nested earlier property retained');
equal(nested.right, 2, 'nested later property added');
equal(nested.replace, 'new', 'nested later property overrides');
equal(merged.explicit, undefined, 'undefined explicitly overwrites');
assert(Object.prototype.hasOwnProperty.call(merged, 'explicit'), 'undefined property remains own');

const atomic = merged.atomic as readonly unknown[];
assert(Array.isArray(atomic), 'array remains an array');
equal(atomic.length, 3, 'later array replaces rather than index-merges');
equal(atomic[0], 1, 'replacement array content');
assert(atomic !== arrayValue, 'result array is cloned');
const atomicObject = atomic[1] as Record<string, unknown>;
assert(atomicObject !== arrayValue[1], 'objects inside arrays are cloned');
equal(atomicObject.deep, 'original', 'nested array object content');

const resultFirstOnly = merged.onlyFirst as Settings;
const resultSecondOnly = merged.onlySecond as Settings;
assert(resultFirstOnly !== shared, 'object appearing only in an early layer is cloned');
assert(resultSecondOnly !== shared, 'object appearing only in a late layer is cloned');
assert(resultFirstOnly !== resultSecondOnly, 'shared input identity need not be retained');

(shared as { flag: boolean }).flag = false;
(arrayValue[1] as { deep: string }).deep = 'input-mutated';
equal(resultFirstOnly.flag, true, 'later input object mutation does not affect result');
equal(resultSecondOnly.flag, true, 'shared input mutation does not affect result copies');
equal(atomicObject.deep, 'original', 'nested input mutation does not affect result');

(resultFirstOnly as Record<string, unknown>).flag = 'result-mutated';
atomicObject.deep = 'result-mutated';
equal(shared.flag, false, 'result object mutation does not affect input');
equal(arrayValue[1].deep, 'input-mutated', 'result nested mutation does not affect input');

equal((first.nested as Settings).replace, 'old', 'merge does not mutate earlier layer');
equal((second.nested as Settings).right, 2, 'merge does not mutate later layer');

const nullPrototype = Object.create(null) as Record<string, unknown>;
nullPrototype.value = 9;
const nullResult = mergeSettings([nullPrototype as Settings]);
equal(nullResult.value, 9, 'null-prototype settings object is accepted');

const protoInput: Record<string, unknown> = {};
Object.defineProperty(protoInput, '__proto__', {
  value: { polluted: true },
  enumerable: true,
  writable: true,
  configurable: true,
});
const protoResult = mergeSettings([protoInput as Settings]);
assert(Object.prototype.hasOwnProperty.call(protoResult, '__proto__'), '__proto__ is an own output property');
assert(Object.getPrototypeOf(protoResult) !== (protoResult as Record<string, unknown>).__proto__, '__proto__ does not replace output prototype');
equal(((protoResult as Record<string, unknown>).__proto__ as Settings).polluted, true, '__proto__ value is preserved');
equal(({} as Record<string, unknown>).polluted, undefined, 'Object prototype is not polluted');

const hiddenInput: Record<string, unknown> = { visible: 1 };
Object.defineProperty(hiddenInput, 'hidden', { value: 2, enumerable: false });
const hiddenResult = mergeSettings([hiddenInput as Settings]);
equal(hiddenResult.visible, 1, 'enumerable own property participates');
assert(!Object.prototype.hasOwnProperty.call(hiddenResult, 'hidden'), 'non-enumerable property is ignored');

const sharedAcyclic = { leaf: 4 };
const sharedResult = mergeSettings([{ a: sharedAcyclic, b: sharedAcyclic }]);
equal((sharedResult.a as Settings).leaf, 4, 'first shared reference is accepted');
equal((sharedResult.b as Settings).leaf, 4, 'second shared reference is accepted');

const malformedValues: readonly unknown[] = [
  Number.NaN,
  Number.POSITIVE_INFINITY,
  Number.NEGATIVE_INFINITY,
  [undefined],
  new Date(0),
  function invalidFunction(): void {},
  Symbol('invalid'),
  1n,
];
for (const malformed of malformedValues) {
  expectTypeError(
    () => mergeSettings([{ bad: malformed } as unknown as Settings]),
    `malformed value ${typeof malformed}`,
  );
}

const objectCycle: Record<string, unknown> = {};
objectCycle.self = objectCycle;
expectTypeError(
  () => mergeSettings([objectCycle as Settings]),
  'cyclic object',
);

const arrayCycle: unknown[] = [];
arrayCycle.push(arrayCycle);
expectTypeError(
  () => mergeSettings([{ cycle: arrayCycle } as unknown as Settings]),
  'cyclic array',
);

expectTypeError(
  () => mergeSettings([{ overwritten: Number.NaN } as unknown as Settings, { overwritten: 1 }]),
  'malformed overwritten layer still fails',
);

